* { box-sizing: border-box; }
body { margin: 0; color: #172b38; background: #f3f5f6; font-family: Arial, sans-serif; font-size: 16px; line-height: 1.5; }
.site-header { min-height: 76px; padding: 18px 7%; display: flex; align-items: center; justify-content: space-between; gap: 40px; background: #fff; border-bottom: 1px solid #d8e0e5; }
.brand { font-size: 24px; font-weight: 700; letter-spacing: -0.6px; }
.site-note { color: #53636e; font-size: 12px; max-width: 420px; }
.shell { width: 1050px; max-width: 90%; margin: 32px auto; }
.page-heading { margin: 0 0 24px; }
h1 { margin: 0; font-size: 32px; line-height: 1.3; }
h2 { margin: 0 0 16px; font-size: 22px; }
p { margin: 0 0 16px; }
.eyebrow { color: #53636e; font-size: 14px; }
.panel { background: #fff; border: 1px solid #d8e0e5; border-radius: 12px; padding: 28px; }
.product-grid { display: grid; grid-template-columns: 1fr 1fr; gap: 24px; }
.product-art { position: relative; background: #dce6e9; border-radius: 12px; min-height: 310px; }
.headband { position: absolute; width: 180px; height: 175px; border: 18px solid #304550; border-bottom: 0; border-radius: 100px 100px 0 0; left: 31%; top: 48px; }
.ear-left, .ear-right { position: absolute; width: 54px; height: 100px; background: #304550; border: 8px solid #58717e; border-radius: 22px; top: 158px; }
.ear-left { left: 28%; }
.ear-right { left: 59%; }
.product-info { display: flex; flex-direction: column; justify-content: center; }
.price { font-size: 28px; font-weight: 700; margin: 16px 0; }
.options-grid { display: grid; grid-template-columns: 1fr 1fr; gap: 24px; }
.context { color: #53636e; margin-bottom: 20px; }
.choice { display: flex; align-items: flex-start; gap: 12px; margin: 0 0 18px; padding: 12px; border: 1px solid #d8e0e5; border-radius: 8px; }
.choice input { width: 20px; height: 20px; margin: 3px 0 0; flex-shrink: 0; }
.choice .detail { display: block; color: #53636e; font-size: 14px; }
.muted { color: #53636e; }
.actions { display: flex; align-items: center; justify-content: space-between; gap: 20px; margin-top: 24px; }
button, .actions a { border-radius: 7px; padding: 12px 20px; border: 1px solid #526d7d; background: #fff; color: #203b4c; font: inherit; cursor: pointer; text-decoration: none; }
button[type=submit] { background: #284f65; color: #fff; }
.quantity-row { display: flex; gap: 20px; align-items: center; margin: 20px 0; }
input[type=number] { width: 90px; padding: 10px; margin-left: 12px; font: inherit; border: 1px solid #899ba6; border-radius: 5px; }
.total { font-size: 23px; font-weight: 700; border-top: 1px solid #d8e0e5; margin-top: 20px; padding-top: 20px; }
.footnote { font-size: 13px; color: #53636e; margin-top: 28px; }
.order-line { display: flex; justify-content: space-between; gap: 30px; padding: 10px 0; }

